/// What `oriToBounds` answers with.
pub const OriToBoundsResult = struct {
    x: f64,
    y: f64,
};

/// oriToBounds converts the point `x`, `y`, in ORI's coordinates, to
/// OpenTimelineIO image space within a picture's
/// `available_image_bounds`, the box from `min_x`, `min_y` to `max_x`,
/// `max_y`, whose centre is ORI's origin and whose height is ORI's
/// unit, and writes it to `out_x` and `out_y`.
///
/// C: `otio_ext_ori_ori_to_bounds`
pub fn oriToBounds(x: f64, y: f64, min_x: f64, min_y: f64, max_x: f64, max_y: f64) Error!OriToBoundsResult {
    var out_x: f64 = undefined;
    var out_y: f64 = undefined;
    var out_error: c.Buffer = .{ .data = null, .len = 0 };
    defer c.otio_buffer_free(out_error);
    const status = c.otio_ext_ori_ori_to_bounds(x, y, min_x, min_y, max_x, max_y, &out_x, &out_y, &out_error);
    if (status != .ok) return support.statusError(status, out_error);
    return .{
        .x = out_x,
        .y = out_y,
    };
}

/// What `oriToPixels` answers with.
